import numpy as np
from unittest.mock import patch, DEFAULT as MOCK_DEFAULT

def num_mock_patch_args_sim(patchings):
    sentinels = [MOCK_DEFAULT]
    return len([p for p in patchings if not p.attribute_name and p.new in sentinels])

class Patching:
    def __init__(self, attribute_name, new):
        self.attribute_name = attribute_name
        self.new = new

# Case 1: p.new is a numpy array
patchings = [Patching(None, np.array([-5.5, 3.0]))]

try:
    print(f"Result: {num_mock_patch_args_sim(patchings)}")
except ValueError as e:
    print(f"Caught expected ValueError: {e}")

# Case 2: p.new is the sentinel
patchings_sentinel = [Patching(None, MOCK_DEFAULT)]
print(f"Result with sentinel: {num_mock_patch_args_sim(patchings_sentinel)}")

